function MoldCoatBrushSpinnerMaker.completeMaking(m) local q=1.0+(MoldCoatBrushSpinnerMaker.getQualityBonus()/100); if MoldCoatBrushSpinnerMaker.maker then q=q+(MoldCoatBrushSpinnerMaker.maker.skill/140) end; q=math.min(2.5,q); MoldCoatBrushSpinnerMaker.productStock[m.productType]=(MoldCoatBrushSpinnerMaker.productStock[m.productType] or 0)+m.quantity; MoldCoatBrushSpinnerMaker.totalProducts=MoldCoatBrushSpinnerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MoldCoatBrushSpinnerMaker.maker then MoldCoatBrushSpinnerMaker.maker.itemsMade=MoldCoatBrushSpinnerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MoldCoatBrushSpinnerMaker.maker.skill=math.min(100,MoldCoatBrushSpinnerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrtilnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"moldcoatbrushspinner.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
